-- New in the library
INSERT INTO result_fields (id, "order", type, unit, iso2_code, category, comments, source, commodity_metadata, analysis_metadata, created_by) VALUES
    ('nBR_MapBiomas_col10_ag_gain_after_2020', 2230, 'numeric', 'ha / %', 'BR', 'Agricultural land post 2020', 'New agriculture since 2020: land in a farming class of the MapBiomas Brazil collection 10 map in 2024, the latest MapBiomas year, that was not in one in 2020. Farming classes: pasture (15), sugar cane (20), mosaic of uses (21), oil palm (35), soybean (39), rice (40), other temporary crops (41), coffee (46), citrus (47), other perennial crops (48) and cotton (62). A switch between crops and pasture is not counted, and forest plantation (9) is left out. Feeds agriculture after 2020 for timber. For Brazil only.', 'Souza, C.M., Jr., Shimbo, J.Z., Rosa, M.R., et al. (2020). Reconstructing Three Decades of Land Use and Land Cover Changes in Brazilian Biomes with Landsat Archive and Earth Engine. Remote Sensing, 12(17), 2735. https://doi.org/10.3390/rs12172735. MapBiomas Brazil collection 10: https://brasil.mapbiomas.org', '{"pcrop":{"dataTheme":"commodities","usedForRisk":false},"acrop":{"dataTheme":"commodities","usedForRisk":false},"timber":{"dataTheme":"agri_after_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"nbr_mapbiomasc10_ag_gain_after_2020_prep","geeAssets":["ee.Image(\"projects/mapbiomas-public/assets/brazil/lulc/collection10/mapbiomas_brazil_collection10_integration_v1\")"]}'::jsonb, 'migration'),
    ('GLAD_crop_gain_after_2020', 2240, 'numeric', 'ha / %', NULL, 'Agricultural land post 2020', 'New cropland since 2020: cropland in the newest GLAD annual cropland map (2024) and not in 2020, within the same product. Feeds agriculture after 2020 for timber.', 'Khan et al. (2026). Global annual cropland dynamics 2015–2024. Remote Sensing of Environment, 340, 115438. https://doi.org/10.1016/j.rse.2026.115438. Data: https://glad.umd.edu/dataset/annual-croplands', '{"pcrop":{"dataTheme":"commodities","usedForRisk":false},"acrop":{"dataTheme":"commodities","usedForRisk":false},"timber":{"dataTheme":"agri_after_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_glad_crop_gain_after_2020_prep","geeAssets":["ee.ImageCollection(\"projects/glad/Cropland_Annual_2015_2024/2020\")"]}'::jsonb, 'migration'),
    ('FDaP_tree_crop_gain_after_2020', 2270, 'numeric', 'ha / %', NULL, 'Agricultural land post 2020', 'New tree crops (oil palm, cocoa, rubber and coffee pooled): no tree crop in 2018 or 2020, then a tree crop in both 2022 and 2024, so the change has to hold (the yearly models flicker). Margins round each crop''s threshold keep out plots that hover near it (mostly cocoa under forest canopy): after 2020 a crop must clear its threshold by 0.1, and before 2021 being within 0.15 of it already counts. It still counts young tree crops that only became visible after 2020, so it is a weak signal. Feeds agriculture after 2020 for timber.', 'FDaP (2026). Forest Data Partnership https://developers.google.com/earth-engine/datasets/publisher/forestdatapartnership. Model notes and thresholds: https://github.com/google/forest-data-partnership/tree/main/models/model_2026a', '{"pcrop":{"dataTheme":"commodities","usedForRisk":false},"acrop":{"dataTheme":"commodities","usedForRisk":false},"timber":{"dataTheme":"agri_after_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_fdap_tree_crop_gain_prep","geeAssets":["ee.ImageCollection(\"projects/forestdatapartnership/assets/{palm, cocoa, rubber, coffee}/model_2026a\")"]}'::jsonb, 'migration'),
    ('GPW_cultiv_pasture_gain_after_2020', 2280, 'numeric', 'ha / %', NULL, 'Agricultural land post 2020', 'New cultivated grassland (pasture): cultivated in the newest year of Global Pasture Watch version 1.1 (2024 now, picked up automatically when a newer year is published) and not in 2020 or 2019. Natural and semi-natural grassland is not counted. Version 1.1 (2000-2024) extends version 1 to 2024, with updated 2021 and 2022 maps; the Global Pasture Watch team recommends it for now (https://github.com/wri/global-pasture-watch/discussions/12). It is not yet on Zenodo or in the Earth Engine catalog (which shows version 1, 2000-2022), so the source given here is the version 1 paper. Feeds agriculture after 2020 for timber.', 'Parente, L., et al. (2024). Annual 30-m maps of global grassland class and extent (2000–2022) based on spatiotemporal machine learning. Scientific Data. https://www.nature.com/articles/s41597-024-04139-6', '{"pcrop":{"dataTheme":"commodities","usedForRisk":false},"acrop":{"dataTheme":"commodities","usedForRisk":false},"timber":{"dataTheme":"agri_after_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_gpw_cultiv_pasture_gain_after_2020_prep","geeAssets":["ee.ImageCollection(\"projects/global-pasture-watch/assets/ggc-30m/v1-1/grassland_c\")"]}'::jsonb, 'migration'),
    ('IIASA_planted_2020', 1851, 'numeric', 'ha / %', NULL, 'Planted/plantation forests', 'Planted forest class (31) of the IIASA Global Forest Management map. The map is from 2015 and stands in for 2020. Feeds planted forest in 2020 for timber.', 'Lesiv, M., et al. (2022). Global forest management data for 2015 at a 100 m resolution. Sci Data 9, 199. https://doi.org/10.1038/s41597-022-01332-3', '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"planted_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_iiasa_planted_2020_prep","geeAssets":["ee.Image(\"projects/sat-io/open-datasets/GFM/FML_v3-2\")"]}'::jsonb, 'migration'),
    ('IIASA_plantation_2020', 1853, 'numeric', 'ha / %', NULL, 'Planted/plantation forests', 'Short-rotation plantation class (32, plantation forest) of the IIASA Global Forest Management map. The map is from 2015 and stands in for 2020. Not read by the timber decision tree: on test plots in Thailand, Malaysia and Vietnam it covers rubber and oil palm (tree crops).', 'Lesiv, M., et al. (2022). Global forest management data for 2015 at a 100 m resolution. Sci Data 9, 199. https://doi.org/10.1038/s41597-022-01332-3', '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"plantation_2020","usedForRisk":false}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_iiasa_plantation_2020_prep","geeAssets":["ee.Image(\"projects/sat-io/open-datasets/GFM/FML_v3-2\")"]}'::jsonb, 'migration'),
    ('ESRI_crop_gain_after_2020', 1921, 'numeric', 'ha / %', NULL, 'Agricultural land post 2020', 'Crop gain in 2025 compared to year 2020 of the ESRI LC map (class 5). ESRI_crop_gain_2020_2024 is the same to 2024, kept for existing users until the output column renames; no indicator reads it.', 'Karra, Kontgis, et al. "Global land use/land cover with Sentinel-2 and deep learning."IGARSS 2021-2021 IEEE International Geoscience and Remote Sensing Symposium. IEEE, 2021.', '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"agri_after_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_esri_crop_gain_after_2020_prep","geeAssets":[]}'::jsonb, 'migration'),
    ('ForTy_v2_primary_2020', 1862, 'numeric', 'ha / %', NULL, NULL, 'ForTy version 2 beta time series, yearly 2017-2025, 10 m. Seven probability bands (primary mature, naturally regenerating, planted, plantation, tree crops / agroforestry, other land, primary regrowing); each pixel takes the highest band, with the two primary bands merged. One binary layer per forest class for 2020, plus gain layers (plantation forest gain = primary or naturally regenerating forest in 2020 that is plantation forest in 2025, so a stand in rotation or planted forest turning plantation forest is not counted; tree crop gain = tree crops in 2025 but not in 2020). The timber decision tree reads the 2020 forest classes, the plantation forest gain, and the tree crop gain (one of the agriculture after 2020 layers). Beta: assets and class definitions may change before release.', 'Google Nature Trace, ForTy V2 Beta Earth Engine app (2026). Contact naturalforests@google.com.', '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"primary","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_forty_v2_primary_2020_prep","geeAssets":["ee.ImageCollection(\"projects/nature-trace/assets/forest_typology/v2_beta/2020\")","ee.ImageCollection(\"projects/nature-trace/assets/forest_typology/v2_beta/2025\")"]}'::jsonb, 'migration'),
    ('ForTy_v2_nat_reg_2020', 1863, 'numeric', 'ha / %', NULL, NULL, 'ForTy version 2 beta time series, yearly 2017-2025, 10 m. Seven probability bands (primary mature, naturally regenerating, planted, plantation, tree crops / agroforestry, other land, primary regrowing); each pixel takes the highest band, with the two primary bands merged. One binary layer per forest class for 2020, plus gain layers (plantation forest gain = primary or naturally regenerating forest in 2020 that is plantation forest in 2025, so a stand in rotation or planted forest turning plantation forest is not counted; tree crop gain = tree crops in 2025 but not in 2020). The timber decision tree reads the 2020 forest classes, the plantation forest gain, and the tree crop gain (one of the agriculture after 2020 layers). Beta: assets and class definitions may change before release.', 'Google Nature Trace, ForTy V2 Beta Earth Engine app (2026). Contact naturalforests@google.com.', '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"naturally_reg_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_forty_v2_nat_reg_2020_prep","geeAssets":["ee.ImageCollection(\"projects/nature-trace/assets/forest_typology/v2_beta/2020\")","ee.ImageCollection(\"projects/nature-trace/assets/forest_typology/v2_beta/2025\")"]}'::jsonb, 'migration'),
    ('ForTy_v2_planted_2020', 1864, 'numeric', 'ha / %', NULL, NULL, 'ForTy version 2 beta time series, yearly 2017-2025, 10 m. Seven probability bands (primary mature, naturally regenerating, planted, plantation, tree crops / agroforestry, other land, primary regrowing); each pixel takes the highest band, with the two primary bands merged. One binary layer per forest class for 2020, plus gain layers (plantation forest gain = primary or naturally regenerating forest in 2020 that is plantation forest in 2025, so a stand in rotation or planted forest turning plantation forest is not counted; tree crop gain = tree crops in 2025 but not in 2020). The timber decision tree reads the 2020 forest classes, the plantation forest gain, and the tree crop gain (one of the agriculture after 2020 layers). Beta: assets and class definitions may change before release.', 'Google Nature Trace, ForTy V2 Beta Earth Engine app (2026). Contact naturalforests@google.com.', '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"planted_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_forty_v2_planted_2020_prep","geeAssets":["ee.ImageCollection(\"projects/nature-trace/assets/forest_typology/v2_beta/2020\")","ee.ImageCollection(\"projects/nature-trace/assets/forest_typology/v2_beta/2025\")"]}'::jsonb, 'migration'),
    ('ForTy_v2_plantation_2020', 1865, 'numeric', 'ha / %', NULL, NULL, 'ForTy version 2 beta time series, yearly 2017-2025, 10 m. Seven probability bands (primary mature, naturally regenerating, planted, plantation, tree crops / agroforestry, other land, primary regrowing); each pixel takes the highest band, with the two primary bands merged. One binary layer per forest class for 2020, plus gain layers (plantation forest gain = primary or naturally regenerating forest in 2020 that is plantation forest in 2025, so a stand in rotation or planted forest turning plantation forest is not counted; tree crop gain = tree crops in 2025 but not in 2020). The timber decision tree reads the 2020 forest classes, the plantation forest gain, and the tree crop gain (one of the agriculture after 2020 layers). Beta: assets and class definitions may change before release.', 'Google Nature Trace, ForTy V2 Beta Earth Engine app (2026). Contact naturalforests@google.com.', '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"plantation_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_forty_v2_plantation_2020_prep","geeAssets":["ee.ImageCollection(\"projects/nature-trace/assets/forest_typology/v2_beta/2020\")","ee.ImageCollection(\"projects/nature-trace/assets/forest_typology/v2_beta/2025\")"]}'::jsonb, 'migration'),
    ('ForTy_v2_plantation_forest_gain_after_2020', 1871, 'numeric', 'ha / %', NULL, NULL, 'ForTy version 2 beta time series, yearly 2017-2025, 10 m. Seven probability bands (primary mature, naturally regenerating, planted, plantation, tree crops / agroforestry, other land, primary regrowing); each pixel takes the highest band, with the two primary bands merged. One binary layer per forest class for 2020, plus gain layers (plantation forest gain = primary or naturally regenerating forest in 2020 that is plantation forest in 2025, so a stand in rotation or planted forest turning plantation forest is not counted; tree crop gain = tree crops in 2025 but not in 2020). The timber decision tree reads the 2020 forest classes, the plantation forest gain, and the tree crop gain (one of the agriculture after 2020 layers). Beta: assets and class definitions may change before release.', 'Google Nature Trace, ForTy V2 Beta Earth Engine app (2026). Contact naturalforests@google.com.', '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"plantation_forest_gain_after_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_forty_v2_plantation_forest_gain_after_2020_prep","geeAssets":["ee.ImageCollection(\"projects/nature-trace/assets/forest_typology/v2_beta/2020\")","ee.ImageCollection(\"projects/nature-trace/assets/forest_typology/v2_beta/2025\")"]}'::jsonb, 'migration'),
    ('ForTy_v2_tree_crop_gain_after_2020', 1872, 'numeric', 'ha / %', NULL, NULL, 'ForTy version 2 beta time series, yearly 2017-2025, 10 m. Seven probability bands (primary mature, naturally regenerating, planted, plantation, tree crops / agroforestry, other land, primary regrowing); each pixel takes the highest band, with the two primary bands merged. One binary layer per forest class for 2020, plus gain layers (plantation forest gain = primary or naturally regenerating forest in 2020 that is plantation forest in 2025, so a stand in rotation or planted forest turning plantation forest is not counted; tree crop gain = tree crops in 2025 but not in 2020). The timber decision tree reads the 2020 forest classes, the plantation forest gain, and the tree crop gain (one of the agriculture after 2020 layers). Beta: assets and class definitions may change before release.', 'Google Nature Trace, ForTy V2 Beta Earth Engine app (2026). Contact naturalforests@google.com.', '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"agri_after_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_forty_v2_tree_crop_gain_after_2020_prep","geeAssets":["ee.ImageCollection(\"projects/nature-trace/assets/forest_typology/v2_beta/2020\")","ee.ImageCollection(\"projects/nature-trace/assets/forest_typology/v2_beta/2025\")"]}'::jsonb, 'migration'),
    ('nBR_MapBiomas_col10_forest_Brazil_2020', 2030, 'numeric', 'ha / %', 'BR', 'Tree cover datasets', 'From the MapBiomas Brazil collection 10 map for 2020 (yearly 30 m land use and land cover, 1985-2024, from the MapBiomas network; not an official national dataset). Forest: forest formation (class 3), mangrove (5), floodable forest (6) and wooded sandbank vegetation (49). Savanna formation (4) is left out: cerrado savanna counts as forest under Brazil''s definition, but its trees are mostly below the 5 m height in the FAO definition. Forest plantation: class 9 (silviculture), which also feeds plantation forest in 2020 for timber. For Brazil only.', 'Souza, C.M., Jr., Shimbo, J.Z., Rosa, M.R., et al. (2020). Reconstructing Three Decades of Land Use and Land Cover Changes in Brazilian Biomes with Landsat Archive and Earth Engine. Remote Sensing, 12(17), 2735. https://doi.org/10.3390/rs12172735. MapBiomas Brazil collection 10: https://brasil.mapbiomas.org', '{"pcrop":{"dataTheme":"treecover","usedForRisk":true},"acrop":{"dataTheme":"treecover","usedForRisk":true},"timber":{"usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"nbr_mapbiomasc10_f20_prep","geeAssets":["ee.Image(\"projects/mapbiomas-public/assets/brazil/lulc/collection10/mapbiomas_brazil_collection10_integration_v1\")"]}'::jsonb, 'migration'),
    ('nBR_MapBiomas_col10_silviculture_Brazil_2020', 2060, 'numeric', 'ha / %', 'BR', 'Tree cover datasets', 'From the MapBiomas Brazil collection 10 map for 2020 (yearly 30 m land use and land cover, 1985-2024, from the MapBiomas network; not an official national dataset). Forest: forest formation (class 3), mangrove (5), floodable forest (6) and wooded sandbank vegetation (49). Savanna formation (4) is left out: cerrado savanna counts as forest under Brazil''s definition, but its trees are mostly below the 5 m height in the FAO definition. Forest plantation: class 9 (silviculture), which also feeds plantation forest in 2020 for timber. For Brazil only.', 'Souza, C.M., Jr., Shimbo, J.Z., Rosa, M.R., et al. (2020). Reconstructing Three Decades of Land Use and Land Cover Changes in Brazilian Biomes with Landsat Archive and Earth Engine. Remote Sensing, 12(17), 2735. https://doi.org/10.3390/rs12172735. MapBiomas Brazil collection 10: https://brasil.mapbiomas.org', '{"pcrop":{"dataTheme":"treecover","usedForRisk":true},"acrop":{"dataTheme":"treecover","usedForRisk":true},"timber":{"dataTheme":"plantation_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"nbr_mapbiomasc10_silv20_prep","geeAssets":["ee.Image(\"projects/mapbiomas-public/assets/brazil/lulc/collection10/mapbiomas_brazil_collection10_integration_v1\")"]}'::jsonb, 'migration'),
    ('nBR_MapBiomas_col10_silviculture_gain_after_2020', 2062, 'numeric', 'ha / %', 'BR', 'Planted/plantation forests', 'New forest plantation on 2020 forest: MapBiomas Brazil collection 10 forest classes in 2020 (3, 5, 6, 49) that are forest plantation (class 9) in 2024, the latest MapBiomas year. A stand in rotation, or new plantation forest on pasture, is not counted. Feeds plantation forest gain after 2020 for timber. For Brazil only.', 'Souza, C.M., Jr., Shimbo, J.Z., Rosa, M.R., et al. (2020). Reconstructing Three Decades of Land Use and Land Cover Changes in Brazilian Biomes with Landsat Archive and Earth Engine. Remote Sensing, 12(17), 2735. https://doi.org/10.3390/rs12172735. MapBiomas Brazil collection 10: https://brasil.mapbiomas.org', '{"pcrop":{"dataTheme":"treecover","usedForRisk":false},"acrop":{"dataTheme":"treecover","usedForRisk":false},"timber":{"dataTheme":"plantation_forest_gain_after_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"nbr_mapbiomasc10_silv_gain_after_2020_prep","geeAssets":["ee.Image(\"projects/mapbiomas-public/assets/brazil/lulc/collection10/mapbiomas_brazil_collection10_integration_v1\")"]}'::jsonb, 'migration'),
    ('nBR_MapBiomas_col10_coffee_2020', 2120, 'numeric', 'ha / %', 'BR', 'Commodity datasets', 'From the MapBiomas Brazil collection 10 map for 2020 (not an official national dataset): coffee (class 46), oil palm (35), citrus and other perennial crops (47, 48), and pasture (15). For Brazil only.', 'Souza, C.M., Jr., Shimbo, J.Z., Rosa, M.R., et al. (2020). Reconstructing Three Decades of Land Use and Land Cover Changes in Brazilian Biomes with Landsat Archive and Earth Engine. Remote Sensing, 12(17), 2735. https://doi.org/10.3390/rs12172735. MapBiomas Brazil collection 10: https://brasil.mapbiomas.org', '{"pcrop":{"dataTheme":"commodities","usedForRisk":true},"acrop":{"dataTheme":"commodities","usedForRisk":true},"timber":{"usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"nbr_mapbiomasc10_cof_prep","geeAssets":["ee.Image(\"projects/mapbiomas-public/assets/brazil/lulc/collection10/mapbiomas_brazil_collection10_integration_v1\")"]}'::jsonb, 'migration'),
    ('nBR_MapBiomas_col10_palmoil_2020', 2130, 'numeric', 'ha / %', 'BR', 'Commodity datasets', 'From the MapBiomas Brazil collection 10 map for 2020 (not an official national dataset): coffee (class 46), oil palm (35), citrus and other perennial crops (47, 48), and pasture (15). For Brazil only.', 'Souza, C.M., Jr., Shimbo, J.Z., Rosa, M.R., et al. (2020). Reconstructing Three Decades of Land Use and Land Cover Changes in Brazilian Biomes with Landsat Archive and Earth Engine. Remote Sensing, 12(17), 2735. https://doi.org/10.3390/rs12172735. MapBiomas Brazil collection 10: https://brasil.mapbiomas.org', '{"pcrop":{"dataTheme":"commodities","usedForRisk":true},"acrop":{"dataTheme":"commodities","usedForRisk":true},"timber":{"usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"nbr_mapbiomasc10_po_prep","geeAssets":["ee.Image(\"projects/mapbiomas-public/assets/brazil/lulc/collection10/mapbiomas_brazil_collection10_integration_v1\")"]}'::jsonb, 'migration'),
    ('nBR_MapBiomas_col10_pc_2020', 2140, 'numeric', 'ha / %', 'BR', 'Commodity datasets', 'From the MapBiomas Brazil collection 10 map for 2020 (not an official national dataset): coffee (class 46), oil palm (35), citrus and other perennial crops (47, 48), and pasture (15). For Brazil only.', 'Souza, C.M., Jr., Shimbo, J.Z., Rosa, M.R., et al. (2020). Reconstructing Three Decades of Land Use and Land Cover Changes in Brazilian Biomes with Landsat Archive and Earth Engine. Remote Sensing, 12(17), 2735. https://doi.org/10.3390/rs12172735. MapBiomas Brazil collection 10: https://brasil.mapbiomas.org', '{"pcrop":{"dataTheme":"commodities","usedForRisk":true},"acrop":{"dataTheme":"commodities","usedForRisk":true},"timber":{"usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"nbr_mapbiomasc10_pc_prep","geeAssets":["ee.Image(\"projects/mapbiomas-public/assets/brazil/lulc/collection10/mapbiomas_brazil_collection10_integration_v1\")"]}'::jsonb, 'migration'),
    ('nBR_MapBiomas_col10_soy_2020', 2160, 'numeric', 'ha / %', 'BR', 'Annual crops', 'From the MapBiomas Brazil collection 10 map for 2020 (not an official national dataset): soybean (class 39), and other annual crops: sugar cane (20), rice (40), cotton (62, beta) and other temporary crops (41). For Brazil only.', 'Souza, C.M., Jr., Shimbo, J.Z., Rosa, M.R., et al. (2020). Reconstructing Three Decades of Land Use and Land Cover Changes in Brazilian Biomes with Landsat Archive and Earth Engine. Remote Sensing, 12(17), 2735. https://doi.org/10.3390/rs12172735. MapBiomas Brazil collection 10: https://brasil.mapbiomas.org', '{"pcrop":{"dataTheme":"commodities","usedForRisk":true},"acrop":{"dataTheme":"commodities","usedForRisk":true},"timber":{"usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"nbr_mapbiomasc10_soy_prep","geeAssets":["ee.Image(\"projects/mapbiomas-public/assets/brazil/lulc/collection10/mapbiomas_brazil_collection10_integration_v1\")"]}'::jsonb, 'migration'),
    ('nBR_MapBiomas_col10_annual_crops_2020', 2170, 'numeric', 'ha / %', 'BR', 'Annual crops', 'From the MapBiomas Brazil collection 10 map for 2020 (not an official national dataset): soybean (class 39), and other annual crops: sugar cane (20), rice (40), cotton (62, beta) and other temporary crops (41). For Brazil only.', 'Souza, C.M., Jr., Shimbo, J.Z., Rosa, M.R., et al. (2020). Reconstructing Three Decades of Land Use and Land Cover Changes in Brazilian Biomes with Landsat Archive and Earth Engine. Remote Sensing, 12(17), 2735. https://doi.org/10.3390/rs12172735. MapBiomas Brazil collection 10: https://brasil.mapbiomas.org', '{"pcrop":{"dataTheme":"commodities","usedForRisk":true},"acrop":{"dataTheme":"commodities","usedForRisk":true},"timber":{"usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"nbr_mapbiomasc10_ac_prep","geeAssets":["ee.Image(\"projects/mapbiomas-public/assets/brazil/lulc/collection10/mapbiomas_brazil_collection10_integration_v1\")"]}'::jsonb, 'migration'),
    ('nBR_MapBiomas_col10_pasture_2020', 2200, 'numeric', 'ha / %', 'BR', 'Commodity datasets', 'From the MapBiomas Brazil collection 10 map for 2020 (not an official national dataset): coffee (class 46), oil palm (35), citrus and other perennial crops (47, 48), and pasture (15). For Brazil only.', 'Souza, C.M., Jr., Shimbo, J.Z., Rosa, M.R., et al. (2020). Reconstructing Three Decades of Land Use and Land Cover Changes in Brazilian Biomes with Landsat Archive and Earth Engine. Remote Sensing, 12(17), 2735. https://doi.org/10.3390/rs12172735. MapBiomas Brazil collection 10: https://brasil.mapbiomas.org', '{"pcrop":{"dataTheme":"commodities","usedForRisk":true},"acrop":{"dataTheme":"commodities","usedForRisk":true},"timber":{"usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"nbr_mapbiomasc10_pasture_prep","geeAssets":["ee.Image(\"projects/mapbiomas-public/assets/brazil/lulc/collection10/mapbiomas_brazil_collection10_integration_v1\")"]}'::jsonb, 'migration'),
    ('nCI_Forest_bnetd_2020', 2205, 'numeric', 'ha / %', 'CI', 'Tree cover datasets', 'Forest for 2020 following the FAO definition, i.e., forest land classes 1-7 (dense, open, gallery, secondary/degraded, mangrove, forest plantation/reforestation and swamp forest, each above 30% tree cover as in the national forest definition) plus tree savannah (class 16, trees 5-20 m at 10-30% cover). BNETD note that forest land and wooded savannah together encompass the FAO definition, and the JRC comparison with GFC2020 uses the same classes (Verhegghen et al., 2024, Annex 2). In the independent validation (March 2024) the forest classes reached 81% user''s and producer''s accuracy, tree savannah 45%. Minimum mapping unit 0.5 ha. For Côte d''Ivoire only.', 'BNETD-CIGN (2024). Occupation des sols de la Côte d''Ivoire en 2020 . Centre d''Information Géographique et du Numérique / Bureau National d''Études Techniques et de Developpement, Côte d''Ivoire, with support from the European Union. Data available online from: https://developers.google.com/earth-engine/datasets/catalog/BNETD_land_cover_v1. Methodology (French): https://africageoportal.maps.arcgis.com/sharing/rest/content/items/76dc18767b89472eb89e8aa54e08a6c9/data. Forest definition and validation: https://africageoportal.maps.arcgis.com/sharing/rest/content/items/26a717d4c13f4f3db2c6056f7e5c0bab/data. Verhegghen, A., et al. (2024). Use of national versus global land use maps to assess deforestation risk in the context of the EU Regulation on Deforestation-free products: case study from Côte d''Ivoire . JRC138965, Publications Office of the European Union. https://doi.org/10.2760/7042220. Validation: CLS and TerraSphere (2024). COPERNICUS4GEOGLAM Validation Note Land Cover V2 Côte d''Ivoire . https://africageoportal.maps.arcgis.com/sharing/rest/content/items/0072843eefe545b1b43b0c5b2ebec41a/data', '{"pcrop":{"dataTheme":"treecover","usedForRisk":true},"acrop":{"dataTheme":"treecover","usedForRisk":true},"timber":{"usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"nci_bnetd_forest_2020_prep","geeAssets":["ee.Image(\"BNETD/land_cover/v1/2020\")"]}'::jsonb, 'migration'),
    ('GLAD_cropland_2020', 2250, 'numeric', 'ha / %', NULL, NULL, 'Cropland in 2020 from the GLAD annual cropland maps. Feeds cropland in 2020 for timber (counts when it covers more than 50% of the plot).', 'Khan et al. (2026). Global annual cropland dynamics 2015–2024. Remote Sensing of Environment, 340, 115438. https://doi.org/10.1016/j.rse.2026.115438. Data: https://glad.umd.edu/dataset/annual-croplands', '{"pcrop":{"dataTheme":"commodities","usedForRisk":false},"acrop":{"dataTheme":"commodities","usedForRisk":false},"timber":{"dataTheme":"cropland_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_glad_cropland_2020_prep","geeAssets":["ee.ImageCollection(\"projects/glad/Cropland_Annual_2015_2024/2020\")"]}'::jsonb, 'migration'),
    ('ESRI_crop_2020', 1849, 'numeric', 'ha / %', NULL, NULL, 'Crops class (5) of the 2020 ESRI land cover map. Feeds cropland in 2020 for timber (counts when it covers more than 50% of the plot).', 'Karra, Kontgis, et al. "Global land use/land cover with Sentinel-2 and deep learning." IGARSS 2021-2021 IEEE International Geoscience and Remote Sensing Symposium. IEEE, 2021.', '{"pcrop":{"dataTheme":"commodities","usedForRisk":false},"acrop":{"dataTheme":"commodities","usedForRisk":false},"timber":{"dataTheme":"cropland_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_esri_crop_2020_prep","geeAssets":["ee.ImageCollection(\"projects/sat-io/open-datasets/landcover/ESRI_Global-LULC_10m_TS\")"]}'::jsonb, 'migration'),
    ('ESRI_other_land_2020', 1855, 'numeric', 'ha / %', NULL, NULL, 'Water (1), built-up (7) and snow and ice (9) of the 2020 ESRI land cover map. Bare ground and rangeland are left out, as they mix fallow fields and grazing land. Feeds other land in 2020 for timber. Other land gain: the same classes in each of the two latest years (2024 and 2025) and in neither 2019 nor 2020, so a class that shows for one year only is not counted. Feeds other land gain after 2020 for timber.', 'Karra, Kontgis, et al. "Global land use/land cover with Sentinel-2 and deep learning." IGARSS 2021-2021 IEEE International Geoscience and Remote Sensing Symposium. IEEE, 2021.', '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"other_land_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_esri_other_land_2020_prep","geeAssets":["ee.ImageCollection(\"projects/sat-io/open-datasets/landcover/ESRI_Global-LULC_10m_TS\")"]}'::jsonb, 'migration'),
    ('nBR_MapBiomas_col10_other_land_2020', 1856, 'numeric', 'ha / %', 'BR', NULL, 'From the MapBiomas Brazil collection 10 map. Other land in 2020: only classes that are surely neither forest nor farming: beach, dune and sand (23), urban (24), rocky outcrop (29), mining (30), salt flat (32) and water (33). Grassland (12), wetland (11), other non-vegetated land (25) and aquaculture (31) are left out, as they are less clearly non-forest. Feeds other land in 2020 for timber. Other land gain: the same classes in 2023 and 2024, the latest MapBiomas years, and in neither 2019 nor 2020, so a class that shows for one year only is not counted. Feeds other land gain after 2020 for timber. For Brazil only.', 'Souza, C.M., Jr., Shimbo, J.Z., Rosa, M.R., et al. (2020). Reconstructing Three Decades of Land Use and Land Cover Changes in Brazilian Biomes with Landsat Archive and Earth Engine. Remote Sensing, 12(17), 2735. https://doi.org/10.3390/rs12172735. MapBiomas Brazil collection 10: https://brasil.mapbiomas.org', '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"other_land_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"nbr_mapbiomasc10_other_land_2020_prep","geeAssets":["ee.Image(\"projects/mapbiomas-public/assets/brazil/lulc/collection10/mapbiomas_brazil_collection10_integration_v1\")"]}'::jsonb, 'migration'),
    ('Global_mining_2020', 1859, 'numeric', 'ha / %', NULL, NULL, 'Industrial mining footprint (Tang and Werner 2023, combined with Maus et al. 2020 for completeness), a single snapshot with no dates. Artisanal mining is not covered. Feeds other land in 2020 for timber.', 'Tang, L., and Werner, T. T. (2023). Global mining footprint mapped from high-resolution satellite imagery. Communications Earth &amp; Environment, 4, 134. https://doi.org/10.1038/s43247-023-00805-6. Maus, V., et al. (2020). A global-scale data set of mining areas. Scientific Data, 7, 289. https://doi.org/10.1038/s41597-020-00624-w', '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"other_land_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_global_mining_2020_prep","geeAssets":["ee.FeatureCollection(\"projects/sat-io/open-datasets/global-mining/global_mining_footprints\")","ee.FeatureCollection(\"projects/sat-io/open-datasets/global-mining/global_mining_polygons\")"]}'::jsonb, 'migration'),
    ('nBR_MapBiomas_col10_other_land_gain_after_2020', 1858, 'numeric', 'ha / %', 'BR', NULL, 'From the MapBiomas Brazil collection 10 map. Other land in 2020: only classes that are surely neither forest nor farming: beach, dune and sand (23), urban (24), rocky outcrop (29), mining (30), salt flat (32) and water (33). Grassland (12), wetland (11), other non-vegetated land (25) and aquaculture (31) are left out, as they are less clearly non-forest. Feeds other land in 2020 for timber. Other land gain: the same classes in 2023 and 2024, the latest MapBiomas years, and in neither 2019 nor 2020, so a class that shows for one year only is not counted. Feeds other land gain after 2020 for timber. For Brazil only.', 'Souza, C.M., Jr., Shimbo, J.Z., Rosa, M.R., et al. (2020). Reconstructing Three Decades of Land Use and Land Cover Changes in Brazilian Biomes with Landsat Archive and Earth Engine. Remote Sensing, 12(17), 2735. https://doi.org/10.3390/rs12172735. MapBiomas Brazil collection 10: https://brasil.mapbiomas.org', '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"other_land_gain_after_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"nbr_mapbiomasc10_other_land_gain_after_2020_prep","geeAssets":["ee.Image(\"projects/mapbiomas-public/assets/brazil/lulc/collection10/mapbiomas_brazil_collection10_integration_v1\")"]}'::jsonb, 'migration'),
    ('ESRI_other_land_gain_after_2020', 1875, 'numeric', 'ha / %', NULL, NULL, 'Water (1), built-up (7) and snow and ice (9) of the 2020 ESRI land cover map. Bare ground and rangeland are left out, as they mix fallow fields and grazing land. Feeds other land in 2020 for timber. Other land gain: the same classes in each of the two latest years (2024 and 2025) and in neither 2019 nor 2020, so a class that shows for one year only is not counted. Feeds other land gain after 2020 for timber.', 'Karra, Kontgis, et al. "Global land use/land cover with Sentinel-2 and deep learning." IGARSS 2021-2021 IEEE International Geoscience and Remote Sensing Symposium. IEEE, 2021.', '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"other_land_gain_after_2020","usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_esri_other_land_gain_after_2020_prep","geeAssets":["ee.ImageCollection(\"projects/sat-io/open-datasets/landcover/ESRI_Global-LULC_10m_TS\")"]}'::jsonb, 'migration')
ON CONFLICT (id) DO NOTHING;

-- Changed in the library
UPDATE result_fields SET comments = 'True when more than half of the plot is in permanent water (for a point, when the point falls on water), as a sign the plot may be in the wrong place. It does not change the risk outcome. JRC''s Global Surface Water data for inland water bodies (classes 1, 2, or 7 from the transitions layer); areas outside USGS Global Shoreline Vector (GSV) boundaries for marine; combined in the asset projects/ee-andyarnellgee/assets/water_mask_jrc_usgs.', updated_by = 'migration' WHERE id = 'In_waterbody';
UPDATE result_fields SET commodity_metadata = '{"pcrop":{"dataTheme":"treecover","usedForRisk":true},"acrop":{"dataTheme":"treecover","usedForRisk":true},"timber":{"usedForRisk":true}}'::jsonb, updated_by = 'migration' WHERE id = 'EUFO_2020';
UPDATE result_fields SET commodity_metadata = '{"pcrop":{"dataTheme":"treecover","usedForRisk":true},"acrop":{"dataTheme":"treecover","usedForRisk":true},"timber":{"usedForRisk":true}}'::jsonb, updated_by = 'migration' WHERE id = 'GLAD_Primary';
UPDATE result_fields SET comments = 'Palm probability model (model_2026a). Filtered collection to 2020 data. Presence where probability is above 0.47: the threshold where precision and recall are equal (~89%) on the FDaP model selection set (model_2026a README, Technical validation, Table 6). Shown in the output but not yet used in the risk decision trees.', source = 'FDaP (2026). Forest Data Partnership https://developers.google.com/earth-engine/datasets/publisher/forestdatapartnership. Model notes and thresholds: https://github.com/google/forest-data-partnership/tree/main/models/model_2026a', analysis_metadata = analysis_metadata || '{"geeAssets":["ee.ImageCollection(\"projects/forestdatapartnership/assets/palm/model_2026a\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'Oil_palm_FDaP';
UPDATE result_fields SET comments = 'Coffee probability model (model_2026a). Filtered collection to 2020 data. Presence where probability is above 0.33: the threshold where precision and recall are equal (~71%) on the FDaP model selection set (model_2026a README, Technical validation, Table 6). Shown in the output but not yet used in the risk decision trees.', source = 'FDaP (2026). Forest Data Partnership https://developers.google.com/earth-engine/datasets/publisher/forestdatapartnership. Model notes and thresholds: https://github.com/google/forest-data-partnership/tree/main/models/model_2026a', analysis_metadata = analysis_metadata || '{"geeAssets":["ee.ImageCollection(\"projects/forestdatapartnership/assets/coffee/model_2026a\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'Coffee_FDaP';
UPDATE result_fields SET comments = 'Cocoa probability model (model_2026a). Filtered collection to 2020 data. Presence where probability is above 0.54: the threshold where precision and recall are equal (~94%) on the FDaP model selection set (model_2026a README, Technical validation, Table 6). Shown in the output but not yet used in the risk decision trees.', source = 'FDaP (2026). Forest Data Partnership https://developers.google.com/earth-engine/datasets/publisher/forestdatapartnership. Model notes and thresholds: https://github.com/google/forest-data-partnership/tree/main/models/model_2026a', analysis_metadata = analysis_metadata || '{"geeAssets":["ee.ImageCollection(\"projects/forestdatapartnership/assets/cocoa/model_2026a\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'Cocoa_FDaP';
UPDATE result_fields SET comments = 'Rubber probability model (model_2026a). Filtered collection to 2020 data. Presence where probability is above 0.35: the threshold where precision and recall are equal (~94%) on the FDaP model selection set (model_2026a README, Technical validation, Table 6). Shown in the output but not yet used in the risk decision trees.', source = 'FDaP (2026). Forest Data Partnership https://developers.google.com/earth-engine/datasets/publisher/forestdatapartnership. Model notes and thresholds: https://github.com/google/forest-data-partnership/tree/main/models/model_2026a', analysis_metadata = analysis_metadata || '{"geeAssets":["ee.ImageCollection(\"projects/forestdatapartnership/assets/rubber/model_2026a\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'Rubber_FDaP';
UPDATE result_fields SET commodity_metadata = '{"pcrop":{"dataTheme":"disturbance_before","usedForRisk":true},"acrop":{"dataTheme":"disturbance_before","usedForRisk":true},"timber":{"usedForRisk":false}}'::jsonb, updated_by = 'migration' WHERE id = 'TMF_deg_before_2020';
UPDATE result_fields SET commodity_metadata = '{"pcrop":{"dataTheme":"disturbance_before","usedForRisk":true},"acrop":{"dataTheme":"disturbance_before","usedForRisk":true},"timber":{"usedForRisk":false}}'::jsonb, updated_by = 'migration' WHERE id = 'TMF_def_before_2020';
UPDATE result_fields SET commodity_metadata = '{"pcrop":{"dataTheme":"disturbance_before","usedForRisk":true},"acrop":{"dataTheme":"disturbance_before","usedForRisk":true},"timber":{"usedForRisk":false}}'::jsonb, updated_by = 'migration' WHERE id = 'GFC_loss_before_2020';
UPDATE result_fields SET comments = 'Binary mask of confirmed alerts (class 3) in 2019 & 2020, from the latest weekly RADD release.', commodity_metadata = '{"pcrop":{"dataTheme":"disturbance_before","usedForRisk":true},"acrop":{"dataTheme":"disturbance_before","usedForRisk":true},"timber":{"usedForRisk":false}}'::jsonb, updated_by = 'migration' WHERE id = 'RADD_before_2020';
UPDATE result_fields SET commodity_metadata = '{"pcrop":{"dataTheme":"disturbance_before","usedForRisk":true},"acrop":{"dataTheme":"disturbance_before","usedForRisk":true},"timber":{"usedForRisk":false}}'::jsonb, updated_by = 'migration' WHERE id = 'GLAD-L_before_2020';
UPDATE result_fields SET commodity_metadata = '{"pcrop":{"dataTheme":"disturbance_before","usedForRisk":true},"acrop":{"dataTheme":"disturbance_before","usedForRisk":true},"timber":{"usedForRisk":false}}'::jsonb, updated_by = 'migration' WHERE id = 'GLAD-S2_before_2020';
UPDATE result_fields SET comments = 'Binary mask of confirmed alerts (class 3) from 2021 onward, from the latest weekly RADD release. RADD can take up to 90 days to confirm an alert, so the newest ones show up later.', updated_by = 'migration' WHERE id = 'RADD_after_2020';
UPDATE result_fields SET comments = 'Binary mask of high-confidence vegetation disturbance alerts (classes 3, 6, 7, 8) filtered by forest habitat (JRC GFC2020). The Earth Engine collection only holds recent alerts (test plots checked in November 2026 had alerts from 2025 and 2026 but none from 2024), so a plot flagged by DIST alone can read differently a year later.', updated_by = 'migration' WHERE id = 'DIST_after_2020';
UPDATE result_fields SET comments = 'Binary mask of aggregate confirmed GLAD Landsat forest alerts (confidence >= 2) from 2021 to the current year (the newest year is picked up automatically). GLAD did not publish a 2024final asset, so 2024 comes from the 2023final asset, which stops in early July 2024: later 2024 alerts are missing. 2025 onwards comes from GLAD''s rolling UpdResult collection. Note: 2015 and 2016 assets do not exist in GEE.', updated_by = 'migration' WHERE id = 'GLAD-L_after_2020';
UPDATE result_fields SET comments = 'Primary forest class (10) from the Global Forest Types map V2 (forest extent of GFC2020 V4).', source = 'Bourgoin, C., Achard, F., Beuchle, R., Carboni, S., Carreiras, J., Korosuo, A., Rotllan-Puig, X., Simonetti, D., Colditz, R. (2026). Global map of forest types 2020 - version 2. European Commission, Joint Research Centre (JRC) [Dataset]. https://doi.org/10.2905/JRC.NP3B8MG.', analysis_metadata = analysis_metadata || '{"geeAssets":["ee.Image(\"JRC/GFC2020_subtypes/V2\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'GFT_primary';
UPDATE result_fields SET comments = 'Intact Forest Landscape binary map (1 is IFL). No decision tree reads it: an intact forest landscape is a block of at least 500 km² that can take in treeless land and water, so it does not show primary forest at plot scale.', commodity_metadata = '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"primary","usedForRisk":false}}'::jsonb, updated_by = 'migration' WHERE id = 'IFL_2020';
UPDATE result_fields SET comments = 'Naturally regenerating forest class (1) from the Global Forest Types map V2 (forest extent of GFC2020 V4).', source = 'Bourgoin, C., Achard, F., Beuchle, R., Carboni, S., Carreiras, J., Korosuo, A., Rotllan-Puig, X., Simonetti, D., Colditz, R. (2026). Global map of forest types 2020 - version 2. European Commission, Joint Research Centre (JRC) [Dataset]. https://doi.org/10.2905/JRC.NP3B8MG.', analysis_metadata = analysis_metadata || '{"geeAssets":["ee.Image(\"JRC/GFC2020_subtypes/V2\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'GFT_naturally_regenerating';
UPDATE result_fields SET comments = 'Planted and plantation forests class (20) from the Global Forest Types map V2 (forest extent of GFC2020 V4). Not read by the timber decision tree, as the class merges planted forest and plantation forest, which the timber decision tree keeps apart.', source = 'Bourgoin, C., Achard, F., Beuchle, R., Carboni, S., Carreiras, J., Korosuo, A., Rotllan-Puig, X., Simonetti, D., Colditz, R. (2026). Global map of forest types 2020 - version 2. European Commission, Joint Research Centre (JRC) [Dataset]. https://doi.org/10.2905/JRC.NP3B8MG.', commodity_metadata = '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"planted_2020","usedForRisk":false}}'::jsonb, analysis_metadata = analysis_metadata || '{"geeAssets":["ee.Image(\"JRC/GFC2020_subtypes/V2\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'GFT_planted_plantation';
UPDATE result_fields SET comments = 'Planted and plantation forest classes (31, 32) of the IIASA Global Forest Management map together, as released before the split into the two rows below. Kept for existing users until the column renames; it feeds no indicator.', commodity_metadata = '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"usedForRisk":false}}'::jsonb, updated_by = 'migration' WHERE id = 'IIASA_planted_plantation';
UPDATE result_fields SET commodity_metadata = '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"treecover_after_2020","usedForRisk":false}}'::jsonb, updated_by = 'migration' WHERE id = 'TMF_regrowth_2024';
UPDATE result_fields SET commodity_metadata = '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"treecover_after_2020","usedForRisk":false}}'::jsonb, updated_by = 'migration' WHERE id = 'ESRI_2024_TC';
UPDATE result_fields SET comments = 'Palm probability model (model_2026a). Filtered collection to 2024 data. Presence where probability is above 0.47: the threshold where precision and recall are equal (~89%) on the FDaP model selection set (model_2026a README, Technical validation, Table 6). Shown in the output but not yet used in the risk decision trees.', source = 'FDaP (2026). Forest Data Partnership https://developers.google.com/earth-engine/datasets/publisher/forestdatapartnership. Model notes and thresholds: https://github.com/google/forest-data-partnership/tree/main/models/model_2026a', analysis_metadata = analysis_metadata || '{"geeAssets":["ee.ImageCollection(\"projects/forestdatapartnership/assets/palm/model_2026a\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'Oil_palm_2024_FDaP';
