UPDATE result_fields SET comments = 'Coffee probability model (model_2026a). Filtered collection to 2024 data. Presence where probability is above 0.33: the threshold where precision and recall are equal (~71%) on the FDaP model selection set (model_2026a README, Technical validation, Table 6). Shown in the output but not yet used in the risk decision trees.', source = 'FDaP (2026). Forest Data Partnership https://developers.google.com/earth-engine/datasets/publisher/forestdatapartnership. Model notes and thresholds: https://github.com/google/forest-data-partnership/tree/main/models/model_2026a', analysis_metadata = analysis_metadata || '{"geeAssets":["ee.ImageCollection(\"projects/forestdatapartnership/assets/coffee/model_2026a\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'Coffee_FDaP_2024';
UPDATE result_fields SET comments = 'Cocoa probability model (model_2026a). Filtered collection to 2024 data. Presence where probability is above 0.54: the threshold where precision and recall are equal (~94%) on the FDaP model selection set (model_2026a README, Technical validation, Table 6). Shown in the output but not yet used in the risk decision trees.', source = 'FDaP (2026). Forest Data Partnership https://developers.google.com/earth-engine/datasets/publisher/forestdatapartnership. Model notes and thresholds: https://github.com/google/forest-data-partnership/tree/main/models/model_2026a', analysis_metadata = analysis_metadata || '{"geeAssets":["ee.ImageCollection(\"projects/forestdatapartnership/assets/cocoa/model_2026a\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'Cocoa_2024_FDaP';
UPDATE result_fields SET comments = 'Crop gain in 2025 compared to year 2020 of the ESRI LC map (class 5). ESRI_crop_gain_2020_2024 is the same to 2024, kept for existing users until the output column renames; no indicator reads it.', commodity_metadata = '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"usedForRisk":false}}'::jsonb, analysis_metadata = analysis_metadata || '{"geeAssets":[]}'::jsonb, updated_by = 'migration' WHERE id = 'ESRI_crop_gain_2020_2024';
UPDATE result_fields SET comments = 'Logging concessions from GFW (polygon data). Shown as Ind_11_logging_concession_before_2020 for existing users; no decision tree reads it, as a concession shows where logging is allowed, not what happened to the forest after 2020.', commodity_metadata = '{"pcrop":{"usedForRisk":false},"acrop":{"usedForRisk":false},"timber":{"dataTheme":"logging_concession","usedForRisk":false}}'::jsonb, updated_by = 'migration' WHERE id = 'GFW_logging_before_2020';
