UPDATE result_fields SET category = 'Commodity datasets', comments = 'Land that IDEAM''s 2020 forest / non-forest map shows as non-forest where the JRC global forest cover map 2020 (GFC2020, version 2) shows forest (class 4 of a cross-tabulation of the two maps). Counted with the commodity datasets, as land not in forest in 2020; it does not name a crop. For Colombia only.', source = 'IDEAM (Instituto de Hidrología, Meteorología y Estudios Ambientales), Colombia. Forest / non-forest map 2020. Cross-tabulated with the JRC global map of forest cover 2020, version 2.', analysis_metadata = analysis_metadata || '{"geeAssets":["ee.Image(\"projects/ee-whisp/assets/nCO/ideam_2020_geo_EUFO\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'nCO_ideam_eufo_commission_2020';
