UPDATE result_fields SET category = 'Tree cover datasets', comments = 'Silviculture (class 9) of TerraClass 2020 for the Amazon and Cerrado biomes: monospecific commercial plantation forests, mostly eucalyptus and pine (official national data). Also feeds plantation forest in 2020 for timber. For Brazil only.', source = 'INPE and Embrapa. TerraClass 2020 , land use and land cover maps of the Amazon and Cerrado biomes. Method: Almeida, C.A., Coutinho, A.C., Esquerdo, J.C.D.M., et al. (2016). High spatial resolution land use and land cover mapping of the Brazilian Legal Amazon in 2008 using Landsat-5/TM and MODIS data. Acta Amazonica, 46(3), 291-302. https://doi.org/10.1590/1809-4392201505504', commodity_metadata = '{"pcrop":{"dataTheme":"treecover","usedForRisk":true},"acrop":{"dataTheme":"treecover","usedForRisk":true},"timber":{"dataTheme":"plantation_2020","usedForRisk":true}}'::jsonb, analysis_metadata = analysis_metadata || '{"geeAssets":["ee.Image(\"projects/ee-whisp/assets/NBR/terraclass_amz_2020\")","ee.Image(\"projects/ee-whisp/assets/NBR/terraclass_cer_2020\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'nBR_INPE_TCsilviculture_Amazon_2020';
