UPDATE result_fields SET category = 'Datasets of disturbances before 2020-12-31', comments = 'Deforestation mapped by INPE''s PRODES (official national data, all biomes) up to 31 December 2020. PRODES years run from 1 August, so this uses a copy of PRODES cut at the end of 2020. Outside the Amazon, PRODES also maps the loss of other native vegetation (other wooded land and grassland). For Brazil only.', source = 'INPE, PRODES, via TerraBrasilis: https://terrabrasilis.dpi.inpe.br. Assis, L.F.F.G., Ferreira, K.R., Vinhas, L., et al. (2019). TerraBrasilis: A Spatial Data Analytics Infrastructure for Large-Scale Thematic Mapping. ISPRS International Journal of Geo-Information, 8(11), 513. https://doi.org/10.3390/ijgi8110513', commodity_metadata = '{"pcrop":{"dataTheme":"disturbance_before","usedForRisk":true},"acrop":{"dataTheme":"disturbance_before","usedForRisk":true},"timber":{"usedForRisk":false}}'::jsonb, analysis_metadata = analysis_metadata || '{"geeAssets":["ee.Image(\"projects/ee-whisp/assets/NBR/nbr_inpe_prodes_dec2020\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'nBR_PRODES_deforestation_Brazil_before_2020';
UPDATE result_fields SET category = 'Datasets of disturbances before 2020-12-31', comments = 'Forest degradation alerts from INPE''s DETER for the Amazon (official national data): burn scars, disordered selective logging and other degradation (classes CICATRIZ_DE_QUEIMADA, CS_DESORDENADO, DEGRADACAO) seen from 2 August 2016 to 31 December 2020. Geometric selective logging (CS_GEOMETRICO) is left out, to match Brazil''s forest reference emission level. For Brazil only.', source = 'INPE, DETER, via TerraBrasilis: https://terrabrasilis.dpi.inpe.br. Diniz, C.G., Souza, A.A.A., Santos, D.C., et al. (2015). DETER-B: The New Amazon Near Real-Time Deforestation Detection System. IEEE Journal of Selected Topics in Applied Earth Observations and Remote Sensing, 8(7), 3619-3628. https://doi.org/10.1109/JSTARS.2015.2437075', commodity_metadata = '{"pcrop":{"dataTheme":"disturbance_before","usedForRisk":true},"acrop":{"dataTheme":"disturbance_before","usedForRisk":true},"timber":{"usedForRisk":false}}'::jsonb, analysis_metadata = analysis_metadata || '{"geeAssets":["ee.FeatureCollection(\"projects/ee-whisp/assets/NBR/deter_amz_16apr2025\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'nBR_DETER_forestdegradation_Amazon_before_2020';
UPDATE result_fields SET category = 'Datasets of disturbances after 2020-12-31', comments = 'Deforestation mapped by INPE''s PRODES (official national data, all biomes) in the PRODES years 2021 to 2023, the latest in the Earth Engine copy. A PRODES year runs from August to July, so 2021 starts in August 2020. Outside the Amazon, PRODES also maps the loss of other native vegetation. For Brazil only.', source = 'INPE, PRODES, via TerraBrasilis: https://terrabrasilis.dpi.inpe.br. Assis, L.F.F.G., Ferreira, K.R., Vinhas, L., et al. (2019). TerraBrasilis: A Spatial Data Analytics Infrastructure for Large-Scale Thematic Mapping. ISPRS International Journal of Geo-Information, 8(11), 513. https://doi.org/10.3390/ijgi8110513', analysis_metadata = analysis_metadata || '{"geeAssets":["ee.Image(\"projects/ee-whisp/assets/NBR/prodes_brasil_2023\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'nBR_PRODES_deforestation_Brazil_after_2020';
UPDATE result_fields SET category = 'Datasets of disturbances after 2020-12-31', comments = 'Forest degradation alerts from INPE''s DETER for the Amazon (official national data): burn scars, disordered selective logging and other degradation seen from 1 January 2021 up to 4 April 2025 (the Earth Engine copy is a static April 2025 snapshot). Geometric selective logging is left out, to match Brazil''s forest reference emission level. For Brazil only.', source = 'INPE, DETER, via TerraBrasilis: https://terrabrasilis.dpi.inpe.br. Diniz, C.G., Souza, A.A.A., Santos, D.C., et al. (2015). DETER-B: The New Amazon Near Real-Time Deforestation Detection System. IEEE Journal of Selected Topics in Applied Earth Observations and Remote Sensing, 8(7), 3619-3628. https://doi.org/10.1109/JSTARS.2015.2437075', analysis_metadata = analysis_metadata || '{"geeAssets":["ee.FeatureCollection(\"projects/ee-whisp/assets/NBR/deter_amz_16apr2025\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'nBR_DETER_forestdegradation_Amazon_after_2020';
