UPDATE result_fields SET comments = 'ForTy (forest typology) version 1, 2020, 10 m. Five class score bands (0-250); each pixel takes its highest-scoring class (primary, naturally regenerating, planted, plantation, tree crops / agroforestry) or "other". One binary layer per class, plus forest = any forest class. Present-but-unused since the V2 time series (below) replaced it on the timber baselines.', source = 'Google Nature Trace and IIASA (2025). ForTy: a global forest typology for 2020. Preprint, https://eartharxiv.org/repository/view/13130', updated_by = 'migration' WHERE id = 'ForTy_forest_2020';
